#pragma once

#include <cstddef>
#include <cstdint>
#include <span>
#include <string_view>

namespace TextRepair {

// Layout of one font in reference-fingerprints.inc (generated by scripts/generate-reference-fingerprints.mjs).
struct ReferenceFontData {
  const char *name;
  const uint64_t *fingerprints;  // ascending
  const uint32_t *offsets;       // count + 1 entries into codepoints
  const uint32_t *codepoints;
  size_t count;
};

class ReferenceFont {
 public:
  explicit ReferenceFont(const ReferenceFontData &data) : data_(data) {}

  // The codepoints this font draws with the outline, canonical first; empty if the font has no such outline.
  std::span<const uint32_t> lookup(uint64_t fingerprint) const;
  std::string_view name() const { return data_.name; }

 private:
  const ReferenceFontData &data_;
};

// The reference font for a PDF font name, or nullptr. Names are normalised as poppler-native 2.3.0 did: a subset
// tag ("ABCDEF+") and a trailing "MT" are dropped, so "ABCDEF+ArialMT" finds Arial and "Arial-BoldMT" Arial-Bold.
const ReferenceFont *referenceFontFor(std::string_view pdfFontName);

}  // namespace TextRepair
